# Differential test: levels generated by the original 32-bit 1.10f D2Common.dll versus the native x64
# D2Common.dll. Needs the user's own Diablo II 1.10 install for the original DLLs (never copied into the repo).
#
#   .\tools\x64\Run-D2LevelDiff.ps1 [-GameDir "C:\games\Diablo II 1.10"] [-Seeds 0x1234,0xBEEF]
param(
    [string]$GameDir = "C:\games\Diablo II 1.10",
    [string]$X64Dir = "$PSScriptRoot\..\..\out\build\X64Dlls\runtime\Release",
    [string[]]$Seeds = @("0x12345678")
)
$ErrorActionPreference = "Stop"
$root = (Resolve-Path "$PSScriptRoot\..\..").Path
$vs = "C:\Program Files\Microsoft Visual Studio\18\Community\VC\Auxiliary\Build\vcvarsall.bat"
$work = Join-Path $root "out\d2level"; New-Item -ItemType Directory -Force $work | Out-Null
$src = "$root\tools\x64\D2LevelTest.cpp"
$core = Join-Path $GameDir "D2SE\CORES\1.10f"
if (-not (Test-Path "$core\D2Common.dll")) { throw "Original 1.10f D2CMP.dll not found in $core" }

# The x86 side reads the MPQs through a 32-bit StormLib (see tools/x64/RefStorm.h); Run-D2CommonLoad.ps1 builds it.
$stormLibSrc = "$root\modern\external\StormLib"
$stormLib32 = "$root\out\d2commonload\stormlib-x86"
if (-not (Test-Path "$stormLib32\Release\StormLib.lib")) {
    cmake -S $stormLibSrc -B $stormLib32 -A Win32 -DSTORM_USE_BUNDLED_LIBRARIES=ON -DBUILD_SHARED_LIBS=OFF -DSTORM_SKIP_INSTALL=ON -DSTORM_BUILD_TESTS=OFF | Out-Null
    cmake --build $stormLib32 --config Release | Out-Null
    if (-not (Test-Path "$stormLib32\Release\StormLib.lib")) { throw "32-bit StormLib build failed" }
}

foreach ($arch in "x86", "x64") {
    $extra = if ($arch -eq "x86") { "/MD /I`"$stormLibSrc\src`" `"$stormLib32\Release\StormLib.lib`" advapi32.lib user32.lib" } else { "" }
    cmd /c "set PATH=%PATH%;C:\Program Files (x86)\Microsoft Visual Studio\Installer&& `"$vs`" $arch >nul 2>&1 && cd /d `"$work`" && cl /nologo /EHsc /std:c++17 /I`"$PSScriptRoot`" /Fe:D2LevelTest_$arch.exe /Fo:D2LevelTest_$arch.obj `"$src`" $extra > build_$arch.txt 2>&1" | Out-Null
    if (-not (Test-Path "$work\D2LevelTest_$arch.exe")) { Get-Content "$work\build_$arch.txt" | Select-Object -Last 10; throw "build failed ($arch)" }
}

Write-Host "--- original 32-bit"
& "$work\D2LevelTest_x86.exe" $core $GameDir "$work\original_x86.txt" @Seeds
if ($LASTEXITCODE -ne 0) { Write-Host "FAIL: original exited $LASTEXITCODE"; exit 1 }
Write-Host "--- native x64"
& "$work\D2LevelTest_x64.exe" (Resolve-Path $X64Dir).Path $GameDir "$work\native_x64.txt" @Seeds
if ($LASTEXITCODE -ne 0) { Write-Host "FAIL: native exited $LASTEXITCODE"; exit 1 }

$a = Get-Content "$work\original_x86.txt"; $b = Get-Content "$work\native_x64.txt"
if ($a.Count -eq 0 -or ($a | Where-Object { $_ -match "^CRASH" })) { Write-Host "FAIL: nothing compared or a library was missing"; exit 1 }
$n = [Math]::Max($a.Count, $b.Count); $diff = 0
for ($i = 0; $i -lt $n; ++$i) {
    if ($a[$i] -ne $b[$i]) { if ($diff -lt 10) { Write-Host "DIFF line $($i+1):`n  original: $($a[$i])`n  native:   $($b[$i])" }; ++$diff }
}
if ($diff) { Write-Host "FAIL: $diff of $n lines differ"; exit 1 }
Write-Host "PASS: $n lines identical between the original 32-bit D2Common and the x64 D2Common"
